'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let icon=n=>`<img class="icon" src="assets/icons/${n}.svg" alt="" aria-hidden="true">`;
const uid=()=>crypto.randomUUID(),today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')},money=n=>new Intl.NumberFormat('uk-UA',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n),safeID=v=>typeof v==='string'&&/^[a-zA-Z0-9-]+$/.test(v),validTypes=['image/jpeg','image/png','image/webp','application/pdf'];
let state={"name":"Демо-користувач","holder":"DEMO USER","card":"0000 0000 0000 0000","account":"Чорна картка","opening":0,"cashback":0,"avatar":null,"transactions":[],"files":[],"extraCards":[],"activeCard":"main","jars":[],"deposits":[],"categories":[],"contacts":[],"messages":[],"regular":[],"creditLimit":0,"notifications":0,"cardSettings":{}};
function pageScrollY(){return document.getElementById('pwa-scroll')?.scrollTop??window.scrollY}
function pageScrollTo(...args){const host=document.getElementById('pwa-scroll');return host?host.scrollTo(...args):window.scrollTo(...args)}
const adminMode=/^\/admin(?:\/|\.html$)/.test(location.pathname);
const initialHash=location.hash.slice(1).split('/');
let route={page:initialHash[0]||'home',id:initialHash[1]},db,submit,showNumber=false,fileURL,loading=true,returnRoute={page:'home'},fileReturn={page:'files'};
function motionMode(){return state.motionPreference||'full'}
function shouldReduceMotion(){const mode=motionMode();return mode==='reduced'||(mode==='system'&&matchMedia('(prefers-reduced-motion: reduce)').matches)}
function compareTransactions(a,b){return ((b.date||'')+'T'+(b.time||'00:00')).localeCompare((a.date||'')+'T'+(a.time||'00:00'))||Number(b.createdAt||0)-Number(a.createdAt||0)||state.transactions.indexOf(b)-state.transactions.indexOf(a)}

const mainCard=()=>({id:'main',account:state.account,card:state.card,opening:state.opening,holder:state.mainHolder||state.holder,color:state.mainColor||'black'}),allCards=()=>[mainCard(),...state.extraCards],activeCard=()=>allCards().find(c=>c.id===state.activeCard)||mainCard(),txFor=(id=activeCard().id)=>state.transactions.filter(t=>(t.cardId||'main')===id).sort(compareTransactions),balance=()=>activeCard().opening+txFor().reduce((s,t)=>s+t.amount,0),currentTx=()=>state.transactions.find(t=>t.id===route.id);
let serverRevision=0,sharedLoading=false,sharedSaving=false;
const blobCache=new WeakMap();
async function serializeState(){const files=await Promise.all(state.files.map(async f=>{if(typeof f.blob==='string')return f;let data=blobCache.get(f.blob);if(!data){data=new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Не вдалося прочитати вкладення'));r.readAsDataURL(f.blob)});blobCache.set(f.blob,data)}return {...f,blob:await data}}));return {...state,files}}
async function hydrateState(value){const files=await Promise.all((value.files||[]).map(async f=>{if(typeof f.blob!=='string')return f;const blob=await(await fetch(f.blob)).blob();blobCache.set(blob,Promise.resolve(f.blob));return {...f,blob}}));return {...value,files}}
async function loadSharedState(force=false){if(sharedLoading||sharedSaving||(!force&&($('#modal').open||document.documentElement.dataset.gesture==='active'||document.documentElement.dataset.editing==='true')))return;sharedLoading=true;try{const r=await fetch('/api/state'+(!force&&serverRevision?'?revision='+serverRevision:''),{cache:'no-store'});if(!r.ok)throw Error('Локальний сервер недоступний. Запустіть python server.py');const record=await r.json();if(!record.unchanged&&!sharedSaving&&(force||!$('#modal').open)){const next=await hydrateState(record.state);if(!sharedSaving&&(force||(!$('#modal').open&&document.documentElement.dataset.gesture!=='active'&&document.documentElement.dataset.editing!=='true'))){state=next;serverRevision=record.revision;if(!loading)render()}}document.documentElement.dataset.storage='saved'}catch(e){document.documentElement.dataset.storage='offline';throw e}finally{sharedLoading=false}}
async function persist(){sharedSaving=true;document.documentElement.dataset.storage='saving';try{const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:serverRevision,state:await serializeState()})});const result=await r.json();if(!r.ok){const e=Error(result.error||'Не вдалося зберегти дані');e.conflict=r.status===409;throw e}serverRevision=result.revision;document.documentElement.dataset.storage='saved'}catch(e){document.documentElement.dataset.storage='offline';throw e}finally{sharedSaving=false}}
async function initializeSharedState(){try{await loadSharedState(true)}catch(e){toast(e.message)}loading=false;render()}
window.addEventListener('focus',()=>loadSharedState().catch(()=>{}));
setInterval(()=>{if(document.visibilityState==='visible')loadSharedState().catch(()=>{})},1500);
window.addEventListener('DOMContentLoaded',initializeSharedState);
async function change(fn){const old=structuredClone(state);try{await fn();await persist();render();return true}catch(e){state=old;if(e.conflict)await loadSharedState(true);toast(e.message);return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function modal(title,html,fn,button='Зберегти'){submit=fn;$('#modal-title').textContent=title;$('#fields').innerHTML=html;$('#error').textContent='';$('#form > .primary').hidden=!fn;$('#form > .primary').textContent=button;if(!$('#modal').open)$('#modal').showModal()}
$('#close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
$('#form').onsubmit=async e=>{e.preventDefault();if(!submit)return;const old=structuredClone(state),button=$('#form > .primary');button.disabled=true;try{await submit(new FormData(e.target));await persist();$('#modal').close();render()}catch(err){state=old;if(err.conflict)await loadSharedState(true);$('#error').textContent=err.message}finally{button.disabled=false}};
const field=(label,name,value='',type='text',extra='')=>`<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`,select=(label,name,options,value)=>`<label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;
const button=(action,label,ico,sub='',data='')=>`<button type="button" class="menu-row" data-action="${action}" ${data}>${icon(ico)}<span>${label}${sub?`<small>${sub}</small>`:''}</span>${icon('caret-right').replace('class="icon"','class="icon chevron"')}</button>`;
const toolbar=(title,right='')=>`<div class="toolbar"><button class="back" data-action="back" aria-label="Назад">${icon('arrow-left')}</button><h1>${title}</h1>${right}</div>`;
const empty=(title,desc,ico='receipt')=>`<div class="empty">${icon(ico)}<b>${title}</b>${desc}</div>`;
function paint(direction='forward'){
 render();
 const screen=$('#screen');
 if(!screen.animate||shouldReduceMotion()||['home','card'].includes(route.page))return;
 screen.getAnimations?.().forEach(a=>a.cancel());
 screen.animate([{opacity:.7},{opacity:1}],{duration:160,easing:'ease-out'});
}

function navigate(page,id){
 delete document.documentElement.dataset.editing;
 if($('#modal').open)$('#modal').close();
 if(fileURL){URL.revokeObjectURL(fileURL);fileURL=null}
 if(page==='detail')returnRoute={...route};
 if(page==='file')fileReturn={...route};
 route={page,id};history.pushState(route,'','#'+page+(id?'/'+id:''));pageScrollTo(0,0);paint();
}
function back(){
 if($('#modal').open)$('#modal').close();
 if(route.page==='receipt')route={page:'detail',id:route.id};
 else if(route.page==='file')route=fileReturn;
 else if(route.page==='detail')route=returnRoute;
 else route={page:'home'};
 history.replaceState(route,'','#'+route.page+(route.id?'/'+route.id:''));pageScrollTo(0,0);paint('back');
}
window.addEventListener('popstate',e=>{if($('#modal').open)$('#modal').close();route=e.state?.page?e.state:{page:'home'};paint('back')});history.replaceState(route,'',location.pathname+location.search+'#'+route.page+(route.id?'/'+route.id:''));
const mask=number=>showNumber?esc(number):esc(number.slice(0,4))+'  ****  ****  '+esc(number.slice(-4));
function rows(items){return items.length?items.map(t=>{const kind=t.amount>0?'income':t.category==='Кафе та ресторани'?'coffee':'shop',i=t.amount>0?'arrow-square-in':kind==='coffee'?'coffee-fill':'shopping-bag-fill';return `<button class="transaction" data-action="tx" data-id="${t.id}"><span class="transaction-icon ${kind}">${icon(i)}</span><span class="tx-content"><strong>${esc(t.title)}</strong><small>${esc(t.note||t.category||'Переказ')}</small></span><span class="tx-amount ${t.amount>0?'green':''}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))} ₴</span></button>`}).join(''):empty('Поки немає операцій','Додайте операцію у налаштуваннях макета.')}
function nav(){const selected=['home','cards','card'].includes(route.page)?'home':['history','detail','files','receipt'].includes(route.page)?'home':route.page;const tabs=[['home','Карти','credit-card-fill'],['credit','Кредити','chart-pie-fill'],['jars','Накопичення','stack-fill'],['more','Ще','circles-four-fill']];return `<div class="tabs-main">${tabs.map(([p,l,i])=>`<button class="tab ${selected===p?'active':''}" data-action="nav" data-page="${p}">${icon(i)}<span>${l}</span></button>`).join('')}</div><button class="tab market-tab ${selected==='market'?'active':''}" data-action="nav" data-page="market">${icon('bag-fill')}<span>Маркет</span></button>`}
function home(){const c=activeCard();return `<header class="home-top"><button class="avatar" data-action="profile" aria-label="Профіль">${state.avatar?`<img src="${state.avatar}" alt="Аватар">`:icon('cat-fill')}</button><button class="top-icon" data-action="nav" data-page="support" aria-label="Підтримка">${icon('chat-circle-fill')}</button><button class="cashback" data-action="nav" data-page="cashback" aria-label="Кешбек">${icon('gift-fill')}<span>${money(state.cashback)} ₴</span></button><span class="divider"></span><button class="top-icon" data-action="nav" data-page="appearance" aria-label="Оформлення">${icon('cat-fill')}</button><button class="top-icon" data-action="nav" data-page="analytics" aria-label="Статистика">${icon('chart-bar-fill')}</button></header><button class="home-balance" data-action="topup" style="width:100%" aria-label="Поповнити картку в макеті">${icon('plus-circle-fill')}<strong>${money(balance())} ₴</strong></button><div class="card-stage"><button class="card-face ${c.id==='white'?'white':''}" data-action="nav" data-page="card" aria-label="Налаштування картки"><img class="card-image" src="assets/black-card.jpg" alt="Чорна картка monobank — візуальний референс"><span class="card-stamp">МАКЕТ · НЕ БАНК</span><span class="card-number">${mask(c.card)}</span></button></div><button class="all-cards" data-action="nav" data-page="cards">${icon('wallet')}Усі картки</button><div class="home-actions"><button data-action="transfer"> <span class="action-circle">${icon('credit-card-fill')}</span>Переказати<br>на картку</button><button data-action="iban"><span class="action-circle">${icon('receipt-fill')}</span>Платіж<br>за IBAN</button><button data-action="nav" data-page="payments"><span class="action-circle">${icon('stack-fill')}</span>Інші<br>платежі</button></div><section class="operation-panel"><div class="section-title"><h2>Операції</h2><button class="pill" data-action="nav" data-page="history">Усі${icon('caret-right')}</button></div>${rows(txFor().slice(0,6))}</section>`}
function historyPage(){const tx=txFor();return toolbar('Операції',`<button class="right blue" data-action="new-tx" aria-label="Додати операцію">${icon('plus')}</button>`)+`<div class="page"><div class="search">${icon('magnifying-glass')}<input id="search" placeholder="Пошук операцій" aria-label="Пошук операцій"></div><div id="tx-list">${grouped(tx)}</div></div>`}
function grouped(tx){tx=[...tx].sort(compareTransactions);let date='';return tx.length?tx.map(t=>{let head='';if(date!==t.date){date=t.date;head=`<h3 class="date-heading">${esc(new Date(t.date+'T12:00:00').toLocaleDateString('uk-UA',{day:'numeric',month:'long',year:'numeric'}))}</h3>`}return head+rows([t])}).join(''):empty('Операцій не знайдено','Спробуйте інший запит або додайте операцію.')}
function detail(){const t=currentTx();if(!t)return toolbar('Операція')+empty('Операцію видалено','Поверніться на головний екран.');const months=['чер','лип','сер','вер','жов','лис'];const files=state.files.filter(f=>f.txId===t.id);return toolbar('',`<button class="right" data-action="favorite" aria-label="Закріпити операцію">${icon(t.favorite?'star-fill':'star')}</button>`)+`<div class="detail-top"><div class="detail-avatar">${icon(t.amount>0?'arrow-square-in':'credit-card-fill')}</div><h1>${esc(t.title)}</h1><div class="detail-amount ${t.amount>0?'green':''}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))} ₴</div><p>${esc(t.date)} о ${esc(t.time||'12:00')} · ${esc(t.category||'Переказ')}</p></div><div class="chart-panel"><div class="chart"><div class="chart-labels"><span>${money(Math.abs(t.amount))} ₴</span><span>0 ₴</span></div><div class="bars">${months.map((m,i)=>`<div class="bar-column"><div class="bar ${i===5?'active':''}"></div><small>${m}</small></div>`).join('')}</div></div></div><section class="receipt-link"><button class="receipt-link-top" data-action="receipt">${icon('link')}<span><h2>Посилання на квитанцію</h2><p></p></span></button><button class="secondary" data-action="share-receipt">${icon('export')}Поділитись</button></section><div class="detail-menu">${button('split','Розділити витрату','users')}${button('repeat','Повторити платіж','arrows-clockwise')}${button('save-contact','Зберегти картку','credit-card')}${button('receipt','Переглянути PDF-квитанцію','receipt')}${button('regular','Зробити регулярним','clock')}${button('installments','Перевести в розстрочку','chart-pie')}${button('support-tx','Поставити запитання','question')}</div><div class="page"><div class="section-title"><h2>Квитанції та фото</h2><button class="blue" data-action="attach">Додати</button></div>${files.length?fileRows(files):'<p class="info">Прикріпіть власний файл до цієї операції.</p>'}<div class="detail-tools"><button class="secondary" data-action="edit-tx">${icon('pencil-simple')}Змінити</button><button class="secondary red" data-action="delete-tx">${icon('trash')}Видалити</button></div></div>`}
function paper(t){const c=allCards().find(c=>c.id===(t.cardId||'main'))||mainCard();return `<article class="receipt-paper" id="paper"><div class="paper-watermark">МАКЕТ\</div><div class="paper-head"><span class="brand">monobank</span><<br><br></small></div><div class="paper-demo"></div><h2>Квитанція № MOCK-${esc(t.id.slice(0,8).toUpperCase())}<br>від ${esc(t.date)}</h2><h3>Відправник</h3><dl class="paper-grid"><dt>Ім’я</dt><dd>${esc(t.amount>0?t.title:state.name)}</dd><dt>Банк</dt><dd></dd><dt>Платіжний інструмент</dt><dd>${esc(t.amount>0?(t.recipient||'0000 **** **** 0000'):c.card.slice(0,4)+' **** **** '+c.card.slice(-4))}</dd></dl><h3>Одержувач</h3><dl class="paper-grid"><dt>Ім’я</dt><dd>${esc(t.amount>0?state.name:t.title)}</dd><dt>Банк одержувача</dt><dd></dd><dt>Платіжний інструмент</dt><dd>${esc(t.amount>0?c.card.slice(0,4)+' **** **** '+c.card.slice(-4):(t.recipient||'0000 **** **** 0000'))}</dd></dl><h3>Деталі транзакції</h3><dl class="paper-grid"><dt>Сума (грн)</dt><dd>${money(Math.abs(t.amount))}</dd><dt>Комісія (грн)</dt><dd>0.00</dd><dt>Призначення</dt><dd>${esc(t.note||'')}</dd><dt>Дата і час</dt><dd>${esc(t.date)} ${esc(t.time||'12:00')}</dd><dt>Статус</dt><dd></dd></dl><p class="paper-note"></p></article>`}
function receiptPage(){const t=currentTx();if(!t)return toolbar('Квитанція')+empty('Операцію не знайдено','');return toolbar('Квитанція')+`<div class="receipt-page">${paper(t)}</div><div class="receipt-bottom"><button class="primary" data-action="print">Зберегти квитанцію</button></div>`}
function fileRows(files){return [...files].sort((a,b)=>Number(b.pinned)-Number(a.pinned)).map(f=>button('open-file',esc(f.name),f.type==='application/pdf'?'file-pdf':'image',(f.pinned?'Закріплено · ':'')+esc(f.date),`data-id="${f.id}"`)).join('')}
function filesPage(){return toolbar('Квитанції та фото',`<button class="right blue" data-action="add-file" aria-label="Додати файл">${icon('plus')}</button>`)+`<div class="page file-grid"><p class="info">Ваші завантажені файли та прикріплені квитанції.</p>${state.files.length?fileRows(state.files):empty('Додайте перший файл','Фото або PDF до 10 МБ.','image')}</div>`}
function filePage(){const f=state.files.find(f=>f.id===route.id);if(!f)return toolbar('Вкладення')+empty('Файл не знайдено','');fileURL=URL.createObjectURL(f.blob);return toolbar('Квитанція / вкладення',`<button class="right" data-action="pin-file" aria-label="Закріпити файл">${icon(f.pinned?'push-pin-fill':'push-pin')}</button>`)+`<div class="page"><p class="info">${esc(f.name)}</p><div class="file-view">${f.type.startsWith('image/')?`<img src="${fileURL}" alt="Завантажене вкладення">`:`<iframe title="PDF-вкладення" src="${fileURL}"></iframe>`}<div class="file-watermark"><span>МАКЕТ · НЕ БАНК<br>ЗАВАНТАЖЕНИЙ ФАЙЛ</span></div></div><div class="button-group"><button class="small-button" data-action="download-file">Відкрити оригінал</button><button class="small-button red" data-action="delete-file">Видалити</button></div></div>`}
function cardsPage(){return toolbar('Усі картки',`<button class="right blue" data-action="new-card" aria-label="Додати картку">${icon('plus')}</button>`)+`<div class="page card-grid">${allCards().map(c=>`<button class="flat-card ${c.id==='white'?'white':''}" data-action="select-card" data-id="${c.id}"><img src="assets/black-card.jpg" alt="Картка-референс"><span class="flat-name">${esc(c.account)} · МАКЕТ</span><span class="flat-number">${esc(c.card.slice(0,4))} **** **** ${esc(c.card.slice(-4))}</span>${c.id===state.activeCard?`<span class="selected-dot">${icon('check')}</span>`:''}</button>`).join('')}<p class="info">Картки існують лише всередині макета. Банківські рахунки не відкриваються.</p></div>`}
function cardPage(){const c=activeCard();return toolbar(c.account)+`<div class="page"><div class="card-settings-head">${icon('credit-card-fill')}<div><h2>${esc(c.account)}</h2><p class="info">${mask(c.card)}</p></div></div><button class="primary" data-action="card-number">${showNumber?'Приховати номер':'Показати номер картки'}</button><section class="panel">${button('edit-profile','Дані картки та баланс','pencil-simple')}${button('nav','Усі картки','wallet','', 'data-page="cards"')}${button('copy-card','Скопіювати номер','copy')}${button('nav','Операції картки','receipt','', 'data-page="history"')}${button('nav','Квитанції та фото','image','', 'data-page="files"')}</section></div>`}
function morePage(){return `<div class="page"><div class="profile-head"><button class="avatar" data-action="avatar" aria-label="Змінити аватар">${state.avatar?`<img src="${state.avatar}" alt="Аватар">`:icon('cat-fill')}</button><div><h1>${esc(state.name)}</h1><small>Налаштування макета</small></div></div><section class="panel">${button('edit-profile','Профіль та дані картки','gear')}${button('new-tx','Додати операцію','plus')}${button('nav','Квитанції та фото','receipt','', 'data-page="files"')}${button('avatar','Змінити фото профілю','image')}${button('nav','Регулярні платежі','clock','', 'data-page="regular"')}${button('nav','Збережені картки','credit-card','', 'data-page="contacts"')}</section><section class="panel">${button('install','На головний екран','device-mobile')}${button('backup','Резервна копія','download-simple')}${button('restore','Відновити дані','upload-simple')}${button('nav','Про макет','question','', 'data-page="about"')}</section></div>`}
function cashbackPage(){return toolbar('Кешбек')+`<div class="page"><div class="cashback-total">${icon('gift-fill')}<h1>${money(state.cashback)} ₴</h1><p class="muted">Кешбек у макеті</p></div><h2>Категорії місяця</h2><p class="info">Оберіть дві категорії для демонстрації.</p><div class="category-grid">${[['Кафе та ресторани','coffee-fill','3%'],['Покупки','shopping-bag-fill','2%'],['Авто та АЗС','car-fill','2%'],['Розваги','gift-fill','5%']].map(([c,i,p])=>`<button class="category ${state.categories.includes(c)?'selected':''}" data-action="category" data-category="${c}">${icon(i)}<span>${c}</span><small>${p} · ${state.categories.includes(c)?'Обрано':'Обрати'}</small></button>`).join('')}</div></div>`}
function jarsPage(){return `<div class="page"><div class="page-heading"><h1>Накопичення</h1><button data-action="new-jar">Створити</button></div>${state.jars.length?state.jars.map(j=>`<section class="panel"><h2>${esc(j.name)}</h2><div class="jar-number">${money(j.amount)} ₴</div><p class="muted">із ${money(j.target)} ₴</p><div class="progress"><div style="width:${Math.min(100,j.amount/j.target*100)}%"></div></div><div class="button-group"><button class="small-button" data-action="jar-topup" data-id="${j.id}">Поповнити</button><button class="small-button red" data-action="jar-delete" data-id="${j.id}">Видалити</button></div></section>`).join(''):empty('На що збираємо?','Створіть банку та спробуйте поповнення у макеті.','stack-fill')}<p class="info">Це симуляція накопичення. Реальні кошти не зараховуються.</p></div>`}
function creditPage(){return `<div class="page"><div class="page-heading"><h1>Кредити</h1></div><section class="panel"><h2>Покупка частинами</h2><p class="info">Спробуйте розрахунок щомісячного платежу без оформлення кредиту.</p>${field('Сума покупки, ₴','calc-amount',12000,'number','min="1" max="9999999" step="0.01"')}${select('Кількість платежів','calc-months',[[3,'3 платежі'],[6,'6 платежів'],[12,'12 платежів']],6)}<div class="jar-number" id="calc-result">2 000,00 ₴</div><p class="muted">на місяць · без урахування комісій</p></section><p class="info">Навчальний калькулятор. Заявки до банку не надсилаються, кредитні договори не укладаються.</p></div>`}
function analytics(){const tx=txFor(),income=tx.filter(t=>t.amount>0).reduce((s,t)=>s+t.amount,0),expense=-tx.filter(t=>t.amount<0).reduce((s,t)=>s+t.amount,0),cats={};tx.filter(t=>t.amount<0).forEach(t=>cats[t.category||'Інше']=(cats[t.category||'Інше']||0)-t.amount);return toolbar('Статистика')+`<div class="page"><div class="stats"><div class="stat"><small>Надходження</small><b class="green">${money(income)} ₴</b></div><div class="stat"><small>Витрати</small><b>${money(expense)} ₴</b></div></div><h2>Витрати за категоріями</h2>${Object.entries(cats).map(([c,v])=>`<section class="panel"><div class="section-title"><span>${esc(c)}</span><span>${money(v)} ₴</span></div><div class="progress"><div style="width:${expense?v/expense*100:0}%"></div></div></section>`).join('')||empty('Ще немає витрат','Додайте операцію для перегляду статистики.')}<p class="info">За весь час · тільки дані макета.</p></div>`}
function supportPage(){return toolbar('Підтримка макета')+`<div class="page"><div class="support-bubble">Це локальна демонстрація чату, а не підтримка Monobank. Можна залишити нотатку — вона збережеться лише на вашому пристрої.</div>${state.messages.map(m=>`<div class="support-bubble you">${esc(m)}</div>`).join('')}<button class="primary" data-action="message">Написати повідомлення</button></div>`}
function regularPage(){return toolbar('Регулярні платежі')+`<div class="page">${state.regular.length?state.regular.map(r=>button('delete-regular',esc(r.title),'clock',`${money(r.amount)} ₴ · щомісяця · симуляція`,`data-id="${r.id}"`)).join(''):empty('Немає регулярних платежів','Відкрийте операцію та натисніть «Зробити регулярним».','clock')}<p class="info">Це список шаблонів. Автоматичних списань немає. Натисніть шаблон, щоб видалити.</p></div>`}
function contactsPage(){return toolbar('Збережені картки')+`<div class="page">${state.contacts.length?state.contacts.map(c=>button('contact-transfer',esc(c.name),'credit-card',esc(c.card),`data-id="${c.id}"`)).join(''):empty('Немає збережених карток','Збережіть картку з деталей операції.','credit-card')}</div>`}
function appearance(){return toolbar('Оформлення')+`<div class="page"><section class="panel">${button('avatar','Фото профілю','image')}${button('nav','Вибрати картку','credit-card','', 'data-page="cards"')}</section><p class="info">Темна тема відтворює надані скриншоти. Позначення макета є постійним.</p></div>`}
function payments(){return toolbar('Інші платежі')+`<div class="page"><section class="panel">${button('transfer','Переказ на картку','credit-card')}${button('iban','Платіж за IBAN','receipt')}${button('mobile','Поповнити мобільний','device-mobile')}${button('nav','Регулярні платежі','clock','', 'data-page="regular"')}${button('nav','Збережені картки','wallet','', 'data-page="contacts"')}</section><p class="info">Усі платежі всередині макета є симуляціями.</p></div>`}
function market(){return `<div class="page"><div class="page-heading"><h1>Маркет</h1></div><section class="panel">${button('offer','Подарункові сертифікати','gift-fill','Демонстраційний каталог')}${button('offer','Квитки та розваги','bag-fill','Демонстраційний каталог')}${button('offer','Мобільний зв’язок','device-mobile','Демонстраційний каталог')}</section><p class="info">Замовлення і покупки в макеті не виконуються.</p></div>`}
function about(){return toolbar('Про макет')+`<div class="page"><h1>Інтерактивний макет</h1><p class="info">Навчальне відтворення інтерфейсу за наданими скриншотами. Не офіційний застосунок Monobank, не банк, не фінансова послуга.</p><p class="info">Баланс, операції, накопичення й кешбек редагуються локально. Зразки квитанцій містять постійне позначення макета. Реальні перекази та кредитування не виконуються.</p><p class="info">Дані зберігаються у браузері на цьому пристрої. Видалення даних сайту видалить їх. Завантажуйте резервну копію.</p><h2>Джерела оформлення</h2><p class="info">Надані користувачем скриншоти й відео. Картки відтворені HTML/CSS; персонаж і нагороди — кадри з відеореференсу. Іконки Phosphor Icons (MIT) та власні SVG. Усі бренди належать відповідним власникам.</p></div>`}
function syncNavigation(){const host=$('#nav'),mode=route.page==='market'?'market':'bank',markup=nav();if(host.dataset.mode!==mode||!host.children.length){host.innerHTML=markup;host.dataset.mode=mode;return}const template=document.createElement('template');template.innerHTML=markup;const desired=[...template.content.querySelectorAll('button')],existing=[...host.querySelectorAll('button')];if(desired.length!==existing.length){host.innerHTML=markup;return}desired.forEach((button,i)=>{existing[i].className=button.className;const current=button.getAttribute('aria-current');if(current)existing[i].setAttribute('aria-current',current);else existing[i].removeAttribute('aria-current')})}
function render(){if(fileURL){URL.revokeObjectURL(fileURL);fileURL=null}$('#app').className=route.page;$('#nav').hidden=['detail','receipt','file'].includes(route.page);syncNavigation();const pages={home,history:historyPage,detail,receipt:receiptPage,files:filesPage,file:filePage,cards:cardsPage,card:cardPage,more:morePage,cashback:cashbackPage,jars:jarsPage,credit:creditPage,analytics,support:supportPage,regular:regularPage,contacts:contactsPage,appearance,payments,market,about};$('#screen').innerHTML=loading?empty('Завантаження…','Зчитуємо дані з пристрою.','clock'):(pages[route.page]||home)();if($('#search'))$('#search').oninput=e=>$('#tx-list').innerHTML=grouped(txFor().filter(t=>(t.title+' '+(t.note||'')).toLowerCase().includes(e.target.value.toLowerCase())));if($('#f-calc-amount')){const calculate=()=>{const amount=Number($('#f-calc-amount').value),months=Number($('#f-calc-months').value);$('#calc-result').textContent=Number.isFinite(amount)&&amount>0?money(amount/months)+' ₴':'Вкажіть суму'};$('#f-calc-amount').oninput=calculate;$('#f-calc-months').onchange=calculate}}
function profile(){const c=activeCard();modal('Редагування макета',field('Ім’я','name',state.name,'text','required maxlength="60"')+field('Назва картки','account',c.account,'text','required maxlength="40"')+field('Номер картки (16 цифр)','card',c.card,'text','inputmode="numeric" required maxlength="23"')+field('Початковий баланс, ₴','opening',c.opening,'number','required min="-999999999" max="999999999" step="0.01"')+field('Кешбек, ₴','cashback',state.cashback,'number','required min="0" max="9999999" step="0.01"')+'<p class="form-note">Суми змінюються лише у макеті. Не вводьте PIN, CVV або банківські паролі.</p>',f=>{const card=f.get('card').replace(/\s/g,'');if(!/^\d{16}$/.test(card))throw Error('Номер має містити 16 цифр');const name=f.get('name').trim(),account=f.get('account').trim();if(!name||!account)throw Error('Заповніть ім’я і назву');state.name=name;state.cashback=Number(f.get('cashback'));const values={account,card:card.match(/.{4}/g).join(' '),opening:Number(f.get('opening'))};if(c.id==='main')Object.assign(state,values);else Object.assign(state.extraCards.find(x=>x.id===c.id),values)})}
function txForm(id,sign=-1,defaults={}){const old=state.transactions.find(t=>t.id===id),t=old||defaults;modal(old?'Змінити операцію':'Операція макета','<p class="form-note">Симуляція. Гроші не переказуються.</p>'+field('Назва / одержувач','title',t.title||'','text','required maxlength="80"')+select('Тип операції','kind',[[-1,'Витрата'],[1,'Надходження']],old?Math.sign(t.amount):sign)+field('Сума, ₴','amount',t.amount?Math.abs(t.amount):'','number','required min="0.01" max="999999999" step="0.01"')+field('Дата','date',t.date||today(),'date','required')+field('Час','time',t.time||new Date().toTimeString().slice(0,5),'time','required')+select('Категорія','category',[['Перекази','Перекази'],['Покупки','Покупки'],['Кафе та ресторани','Кафе та ресторани'],['Транспорт','Транспорт'],['Інше','Інше']],t.category||'Перекази')+field('Примітка','note',t.note||'','text','maxlength="300"')+field('Реквізити одержувача (необов’язково)','recipient',t.recipient||'','text','maxlength="40"'),f=>{const item={...old,id:old?.id||uid(),createdAt:old?.createdAt||Date.now(),title:f.get('title').trim(),amount:Number(f.get('amount'))*Number(f.get('kind')),date:f.get('date'),time:f.get('time'),category:f.get('category'),note:f.get('note'),recipient:f.get('recipient'),cardId:old?.cardId||activeCard().id};if(!item.title)throw Error('Вкажіть назву');if(old)state.transactions=state.transactions.map(x=>x.id===old.id?item:x);else state.transactions.push(item)})}
function transfer(type='card',defaults={}){const iban=type==='iban',mobile=type==='mobile';modal(iban?'Платіж за IBAN':mobile?'Поповнення мобільного':'Переказ на картку','<p class="form-note">МАКЕТ · Реальний платіж не виконується.</p>'+field(mobile?'Номер телефону':iban?'IBAN':'Номер картки','recipient',defaults.recipient||'','text',`required maxlength="${iban?34:mobile?16:23}"`)+field('Ім’я одержувача / назва','title',defaults.title||'','text','required maxlength="80"')+field('Сума, ₴','amount',defaults.amount?Math.abs(defaults.amount):'','number','required min="0.01" max="999999999" step="0.01"')+field('Призначення','note',defaults.note||'','text','maxlength="300"'),f=>{const recipient=f.get('recipient').replace(/\s/g,'');if(!iban&&!mobile&&!/^\d{16}$/.test(recipient))throw Error('Введіть 16 цифр картки');if(iban&&!/^UA\d{27}$/.test(recipient.toUpperCase()))throw Error('IBAN: UA та 27 цифр');if(mobile&&!/^\+?\d{10,15}$/.test(recipient))throw Error('Перевірте номер телефону');const title=f.get('title').trim();if(!title)throw Error('Вкажіть ім’я');state.transactions.push({id:uid(),title,recipient,amount:-Number(f.get('amount')),date:today(),time:new Date().toTimeString().slice(0,5),note:f.get('note')||'Переказ власних коштів',category:'Перекази',cardId:activeCard().id})},'Додати операцію макета')}
function confirmDelete(title,fn){modal(title,'<p class="form-note">Видалити з локального макета? Дію можна скасувати кнопкою «Закрити» до підтвердження.</p>',fn,'Видалити')}
async function readFile(file){if(!validTypes.includes(file.type)||file.size>10*1024*1024||!file.size)throw Error('Виберіть JPG, PNG, WebP або PDF до 10 МБ');return file}
function addFile(txId){modal('Додати квитанцію / фото',field('Назва','name','','text','maxlength="80"')+'<label for="upload">Фото або PDF до 10 МБ</label><input id="upload" name="file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required>',async f=>{const file=await readFile(f.get('file'));state.files.push({id:uid(),name:f.get('name').trim()||file.name,type:file.type,blob:file,date:new Date().toLocaleDateString('uk-UA'),pinned:false,txId:txId||null})})}
function avatar(){modal('Фото профілю','<label for="avatar-file">JPG, PNG або WebP до 5 МБ</label><input id="avatar-file" name="file" type="file" accept="image/jpeg,image/png,image/webp" required>',async f=>{const file=f.get('file');if(!validTypes.slice(0,3).includes(file.type)||file.size>5*1024*1024)throw Error('Фото має бути JPG, PNG або WebP до 5 МБ');state.avatar=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Не вдалося прочитати фото'));r.readAsDataURL(file)})})}
function newCard(){modal('Додати картку макета',field('Назва','account','','text','required maxlength="40"')+field('Номер картки','card','','text','required maxlength="23" inputmode="numeric"')+field('Початковий баланс, ₴','opening',0,'number','required step="0.01" min="-999999999" max="999999999"'),f=>{const card=f.get('card').replace(/\s/g,'');if(!/^\d{16}$/.test(card))throw Error('Введіть 16 цифр картки');if(!f.get('account').trim())throw Error('Вкажіть назву');state.extraCards.push({id:uid(),account:f.get('account').trim(),card:card.match(/.{4}/g).join(' '),opening:Number(f.get('opening'))})})}
function newJar(){modal('Нова банка',field('Назва','name','','text','required maxlength="60"')+field('Мета, ₴','target','','number','required min="1" max="999999999" step="0.01"'),f=>{if(!f.get('name').trim())throw Error('Вкажіть назву');state.jars.push({id:uid(),name:f.get('name').trim(),target:Number(f.get('target')),amount:0})})}
function split(){const t=currentTx();modal('Розділити витрату',field('Кількість учасників (разом з вами)','people',2,'number','required min="2" max="100" step="1"')+`<p class="info">Сума витрати: ${money(Math.abs(t.amount))} ₴</p><p id="split-result" class="jar-number">${money(Math.abs(t.amount)/2)} ₴</p><p class="form-note">На кожного · розрахунок макета, без запитів оплати.</p>`,null);$('#f-people').oninput=e=>{const n=Number(e.target.value);$('#split-result').textContent=n>=2&&n<=100?money(Math.abs(t.amount)/n)+' ₴':'Вкажіть від 2 до 100 учасників'}}
function installments(){const t=currentTx();modal('Розрахунок розстрочки',select('Кількість платежів','months',[[3,'3 місяці'],[6,'6 місяців'],[12,'12 місяців']],3)+`<div class="jar-number" id="inst-result">${money(Math.abs(t.amount)/3)} ₴</div><p class="form-note">На місяць без урахування комісій. Лише розрахунок; кредит не оформлюється.</p>`,null);$('#f-months').onchange=e=>$('#inst-result').textContent=money(Math.abs(t.amount)/Number(e.target.value))+' ₴'}
function saveContact(){const t=currentTx();modal('Зберегти картку',field('Ім’я','name',t.title,'text','required maxlength="80"')+field('Номер картки','card',t.recipient||'','text','required maxlength="23" inputmode="numeric"'),f=>{const c=f.get('card').replace(/\s/g,'');if(!/^\d{16}$/.test(c))throw Error('Введіть 16 цифр');if(!f.get('name').trim())throw Error('Вкажіть ім’я');state.contacts.push({id:uid(),name:f.get('name').trim(),card:c.match(/.{4}/g).join(' ')})})}
function message(){modal('Повідомлення','<p class="form-note">Зберігається на цьому пристрої. До Monobank не надсилається.</p><label for="message">Текст</label><textarea id="message" name="message" required maxlength="1000"></textarea>',f=>{if(!f.get('message').trim())throw Error('Введіть текст');state.messages.push(f.get('message').trim())},'Зберегти повідомлення')}
async function shareReceipt(){const t=currentTx();const text=`\n${t.title}\n${money(Math.abs(t.amount))} ₴\n${t.date}`;try{if(navigator.share)await navigator.share({title:'Квитанція',text});else{await navigator.clipboard.writeText(text);toast('Текст квитанції скопійовано')}}catch(e){if(e.name!=='AbortError')toast('Не вдалося поділитися. Відкрийте квитанцію і збережіть PDF.')}}
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null}else modal('На головний екран','<p class="info">iPhone: Safari → «Поділитися» → «На початковий екран».<br><br>Android: Chrome → меню → «Встановити застосунок» або «Додати на головний екран».<br><br>Потрібна HTTPS-адреса. Назва значка — «mono макет».</p>',null)}
async function backup(){try{const files=await Promise.all(state.files.map(f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({...f,blob:r.result});r.onerror=reject;r.readAsDataURL(f.blob)})));download(new Blob([JSON.stringify({version:2,state:{...state,files}})],{type:'application/json'}),'mono-mock-backup.json')}catch(e){toast('Не вдалося створити копію')}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function restore(){modal('Відновити копію','<p class="form-note">Ця дія замінить поточні дані макета даними з копії.</p><label for="restore-file">Файл резервної копії</label><input id="restore-file" name="file" type="file" accept="application/json" required>',async f=>{const file=f.get('file');if(file.size>60*1024*1024)throw Error('Копія перевищує 60 МБ');const data=JSON.parse(await file.text()),s=data.state;if(![1,2].includes(data.version)||!s||typeof s.name!=='string'||typeof s.card!=='string'||typeof s.account!=='string'||!Number.isFinite(s.opening)||!Array.isArray(s.transactions)||!Array.isArray(s.files))throw Error('Невірний формат копії');if(!s.transactions.every(t=>safeID(t.id)&&typeof t.title==='string'&&Number.isFinite(t.amount)&&/^\d{4}-\d{2}-\d{2}$/.test(t.date)&&(!t.time||/^\d{2}:\d{2}$/.test(t.time))))throw Error('Пошкоджені операції');for(const x of s.files){if(!safeID(x.id)||typeof x.name!=='string'||typeof x.date!=='string'||!validTypes.includes(x.type)||typeof x.blob!=='string'||!x.blob.startsWith(`data:${x.type};base64,`))throw Error('Пошкоджене вкладення');x.blob=await(await fetch(x.blob)).blob();if(x.blob.size>10*1024*1024)throw Error('Вкладення перевищує 10 МБ')}if(s.avatar&&(!/^data:image\/(jpeg|png|webp);base64,/.test(s.avatar)||s.avatar.length>7*1024*1024))throw Error('Невірне фото профілю');if(s.extraCards&&(!Array.isArray(s.extraCards)||!s.extraCards.every(c=>safeID(c.id)&&typeof c.account==='string'&&typeof c.card==='string'&&Number.isFinite(c.opening))))throw Error('Пошкоджені картки');if(s.jars&&(!Array.isArray(s.jars)||!s.jars.every(j=>safeID(j.id)&&typeof j.name==='string'&&Number.isFinite(j.amount)&&Number.isFinite(j.target)&&j.target>0)))throw Error('Пошкоджені банки');if(s.contacts&&(!Array.isArray(s.contacts)||!s.contacts.every(c=>safeID(c.id)&&typeof c.name==='string'&&typeof c.card==='string')))throw Error('Пошкоджені контакти');if(s.regular&&(!Array.isArray(s.regular)||!s.regular.every(r=>safeID(r.id)&&typeof r.title==='string'&&Number.isFinite(r.amount))))throw Error('Пошкоджені шаблони');if(s.messages&&(!Array.isArray(s.messages)||!s.messages.every(m=>typeof m==='string')))throw Error('Пошкоджені повідомлення');state={...state,...s};state.activeCard=allCards().some(c=>c.id===state.activeCard)?state.activeCard:'main'})}
const actions={
nav:b=>navigate(b.dataset.page),back,profile:()=>navigate('more'),'edit-profile':profile,avatar,'new-tx':()=>txForm(),transfer:()=>transfer(),iban:()=>transfer('iban'),mobile:()=>transfer('mobile'),topup:()=>txForm(null,1,{title:'Поповнення картки',category:'Перекази'}),tx:b=>navigate('detail',b.dataset.id),'edit-tx':()=>txForm(route.id),'delete-tx':()=>{const id=route.id;confirmDelete('Видалити операцію?',()=>{state.transactions=state.transactions.filter(t=>t.id!==id);state.files.forEach(f=>{if(f.txId===id)f.txId=null});route={page:'history'}})},'card-number':()=>{showNumber=!showNumber;render()},'new-card':newCard,'select-card':async b=>{if(await change(()=>state.activeCard=b.dataset.id))navigate('home')},'copy-card':async()=>{try{await navigator.clipboard.writeText(activeCard().card);toast('Номер скопійовано')}catch(e){toast('Копіювання недоступне')}},favorite:()=>change(()=>{const t=currentTx();t.favorite=!t.favorite}),receipt:()=>{const files=state.files.filter(f=>f.txId===route.id).sort((a,b)=>Number(b.pinned)-Number(a.pinned));if(files.length)navigate('file',files[0].id);else navigate('receipt',route.id)},'share-receipt':shareReceipt,print:()=>window.print(),split,repeat:()=>{const t=currentTx();transfer(t.recipient?.startsWith('UA')?'iban':'card',t)},'save-contact':saveContact,regular:()=>{const t=currentTx();modal('Регулярний платіж',`<p class="info">${esc(t.title)} · ${money(Math.abs(t.amount))} ₴<br>Шаблон щомісячного платежу. Автоматичних списань у макеті немає.</p>`,()=>{if(!state.regular.some(r=>r.txId===t.id))state.regular.push({id:uid(),txId:t.id,title:t.title,amount:Math.abs(t.amount)})},'Зберегти шаблон')},installments,'support-tx':()=>navigate('support'),attach:()=>addFile(route.id),'add-file':()=>addFile(),'open-file':b=>navigate('file',b.dataset.id),'pin-file':()=>change(()=>{const f=state.files.find(f=>f.id===route.id);f.pinned=!f.pinned}),'delete-file':()=>{const id=route.id;confirmDelete('Видалити вкладення?',()=>{state.files=state.files.filter(f=>f.id!==id);route={page:'files'}})},'download-file':()=>{const f=state.files.find(f=>f.id===route.id);if(fileURL)window.open(fileURL,'_blank','noopener')},'new-jar':newJar,'jar-topup':b=>{const j=state.jars.find(j=>j.id===b.dataset.id);modal('Поповнити банку',field('Сума, ₴','amount','','number','required min="0.01" max="999999999" step="0.01"')+'<p class="form-note">Додає суму лише до симуляції банки.</p>',f=>{j.amount+=Number(f.get('amount'))})},'jar-delete':b=>confirmDelete('Видалити банку?',()=>{state.jars=state.jars.filter(j=>j.id!==b.dataset.id)}),category:b=>change(()=>{const c=b.dataset.category;if(state.categories.includes(c))state.categories=state.categories.filter(x=>x!==c);else if(state.categories.length<2)state.categories.push(c);else throw Error('Можна обрати дві категорії')}),'delete-regular':b=>confirmDelete('Видалити шаблон?',()=>{state.regular=state.regular.filter(r=>r.id!==b.dataset.id)}),'contact-transfer':b=>{const c=state.contacts.find(c=>c.id===b.dataset.id);transfer('card',{title:c.name,recipient:c.card})},message,offer:()=>modal('Демонстраційний каталог','<p class="info">Цей розділ показує навігацію макета. Оформлення покупок і оплата недоступні.</p>',null),install,backup,restore
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const fn=actions[b.dataset.action];if(fn)Promise.resolve().then(()=>fn(b)).catch(err=>toast(err.message))});
